import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as n,c as i,a2 as p}from"./chunks/framework.CHeM0PsO.js";const E=JSON.parse('{"title":"概念","description":"","frontmatter":{},"headers":[],"relativePath":"ja/concepts/overview.md","filePath":"ja/concepts/overview.md","lastUpdated":1784903584000}'),t={name:"ja/concepts/overview.md"};function o(l,s,c,r,d,h){return n(),i("div",null,[...s[0]||(s[0]=[p('<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h1><h2 id="アーキテクチャ" tabindex="-1">アーキテクチャ <a class="header-anchor" href="#アーキテクチャ" aria-label="Permalink to &quot;アーキテクチャ&quot;">​</a></h2><p>swag2mcp は API 仕様と LLM エージェントの間のブリッジとして機能します：</p><img src="'+a+`" width="800" alt="swag2mcp アーキテクチャ"><h2 id="コアコンセプト" tabindex="-1">コアコンセプト <a class="header-anchor" href="#コアコンセプト" aria-label="Permalink to &quot;コアコンセプト&quot;">​</a></h2><p><strong>Spec</strong> — API ドメインまたはサービスを表す論理コンテナ（例：YouTube、Binance、Open-Meteo）。各 spec は一意の <code>domain</code>、<code>base_url</code>、オプションの <code>auth</code> を持ち、1 つ以上の collection を含みます。また、<code>llm_instruction</code> を設定できます — swag2mcp システムプロンプトに注入される短いヒントで、LLM にこの spec の目的と使用タイミングを伝えます。詳細：<a href="./specs">Specs</a>。</p><p><strong>Collection</strong> — 特定の API を記述する単一の OpenAPI/Swagger/Postman ファイル。<code>location</code>（URL またはローカルファイルパス）を指します。1 つの spec は複数の collection を持つことができます — 例えば、&quot;meteo&quot; spec には &quot;Forecast&quot;、&quot;Air Quality&quot;、&quot;Marine&quot; の collection があり、それぞれ異なる spec ファイルを指します。詳細：<a href="./collections">Collections</a>。</p><p><strong>Tag</strong> — collection 内のエンドポイントのカテゴリ。LLM が適切な操作をより正確に見つけるのに役立ちます。詳細：<a href="./tags">Tags</a>。</p><p><strong>Endpoint</strong> — 特定の HTTP メソッド + パス（例：<code>GET /api/users</code>）。LLM は説明でエンドポイントを見つけ、パラメーターとスキーマを調査し、呼び出すことができます。詳細：<a href="./endpoints">Endpoints</a>。</p><p><strong>Workspace</strong> — swag2mcp が設定、spec キャッシュ、保存されたレスポンス、認証スクリプトを保存するディレクトリ。詳細：<a href="./workspace">Workspace</a>。</p><h2 id="仕組み" tabindex="-1">仕組み <a class="header-anchor" href="#仕組み" aria-label="Permalink to &quot;仕組み&quot;">​</a></h2><ol><li><p><strong>spec または collection を追加</strong> — YAML 設定（<code>~/.swag2mcp/swag2mcp.yaml</code>）で定義します。例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp が各 collection を解析</strong> — タグとエンドポイントを作成し、検索用にインデックス化します。</p></li><li><p><strong>LLM が適切なエンドポイントを見つける</strong> — MCP ツール（<code>search</code>、<code>endpoint_by_tag</code>、<code>inspect</code>）を通じて、LLM は説明で一致するエンドポイントを検索し、パラメーターとリクエストスキーマを確認します。</p></li><li><p><strong>LLM がエンドポイントを呼び出す</strong> — MCP ツール <code>invoke</code> を介して、LLM がリクエストを送信します。swag2mcp は呼び出し前にすべての入力パラメーターをエンドポイントの OpenAPI スキーマに対して検証します（パスパラメーター、クエリパラメーター、ヘッダー、リクエストボディ）。スキーマに一致しないものがある場合、LLM は何が問題かを説明する明確なエラーを受け取ります。検証後、swag2mcp は実際の HTTP 呼び出しを実行し、結果を返します。</p></li><li><p><strong>結果が LLM に返される</strong> — API レスポンスはエージェントに渡されます。大きなレスポンスはワークスペースに保存され、3 つの専用 MCP ツール（<code>response_outline</code>（構造の確認）、<code>response_compress</code>（代表的なサンプルに縮小）、<code>response_slice</code>（特定の断片の抽出））で探索できます。</p></li></ol><p>swag2mcp は LLM と API の世界の間のブリッジです。API 仕様を追加すると、LLM は MCP プロトコルを通じて適切なエンドポイントを見つけ、そのドキュメントを調査し、呼び出します。必要なのは spec を追加して MCP サーバーを起動することだけです。</p><blockquote><p><strong>設定はいつでも編集可能です。</strong> YAML 設定ファイル（<code>~/.swag2mcp/swag2mcp.yaml</code>）は手動で編集できます — spec の追加、認証の変更、設定の調整。編集後は毎回 MCP サーバー（<code>swag2mcp mcp</code>）を再起動して変更を反映してください。</p></blockquote><h2 id="階層" tabindex="-1">階層 <a class="header-anchor" href="#階層" aria-label="Permalink to &quot;階層&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, e.g. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection 1 (spec file, e.g. forecast.yml)</span></span>
<span class="line"><span>        └── Tag 1 (category)</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpoint (POST /api/forecast)</span></span>
<span class="line"><span>        └── Tag 2</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (spec file, e.g. air-quality.yml)</span></span>
<span class="line"><span>        └── Tag 3</span></span>
<span class="line"><span>              └── Endpoint (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const m=e(t,[["render",o]]);export{E as __pageData,m as default};
